1	"use client";
2	
3	import type React from "react";
4	import { SegmentStatus } from "@workspace/db/schema/segment";
5	import { Button } from "@workspace/ui/components/button";
6	import { Combine, Download, Scissors } from "lucide-react";
7	import Link from "next/link";
8	import { useCallback, useMemo, useRef, useState } from "react";
9	import { splitSentences } from "@/features/work/import/split-into-segments";
10	import { AssistPanel } from "./assist-panel.client";
11	import { confirmSegmentAction } from "./confirm-segment.action";
12	import type { SegmentDto } from "./get-work-segments";
13	import { mergeSegmentsAction } from "./merge-segments.action";
14	import { SegmentStatusDot } from "./segment-status-badge.universal";
15	import { splitSegmentAction } from "./split-segment.action";
16	import { updateSegmentAction } from "./update-segment.action";
17	
18	type Mode = "merge" | "normal" | "split";
19	
20	interface EditorProps {
21	  canEdit: boolean;
22	  initialSegments: SegmentDto[];
23	  projectId: string;
24	  workId: string;
25	  workName: string;
26	}
27	
28	export function Editor({
29	  canEdit,
30	  initialSegments,
31	  projectId,
32	  workId,
33	  workName,
34	}: EditorProps): React.JSX.Element {
35	  const [segments, setSegmentsState] = useState<SegmentDto[]>(initialSegments);
36	  const segmentsRef = useRef<SegmentDto[]>(initialSegments);
37	  const [selectedId, setSelectedId] = useState<string | null>(
38	    initialSegments[0]?.id ?? null,
39	  );
40	  const [mode, setMode] = useState<Mode>("normal");
41	  const [mergeSelected, setMergeSelected] = useState<Set<string>>(new Set());
42	  const [saved, setSaved] = useState(false);
43	  const [isConfirming, setIsConfirming] = useState(false);
44	  const [confirmError, setConfirmError] = useState<string | null>(null);
45	  const [structuralError, setStructuralError] = useState<string | null>(null);
46	  const dirtyRef = useRef<Set<string>>(new Set());
47	
48	  const setSegments = useCallback((next: SegmentDto[]): void => {
49	    segmentsRef.current = next;
50	    setSegmentsState(next);
51	  }, []);
52	
53	  const selectedSegment = useMemo(
54	    () => segments.find((segment) => segment.id === selectedId) ?? null,
55	    [segments, selectedId],
56	  );
57	
58	  const progress = useMemo(() => {
59	    const total = segments.length;
60	    const confirmed = segments.filter(
61	      (segment) => segment.status === SegmentStatus.Confirmed,
62	    ).length;
63	    return { confirmed, total };
64	  }, [segments]);
65	
66	  const persistTarget = useCallback(
67	    async (segmentId: string): Promise<void> => {
68	      const segment = segmentsRef.current.find((item) => item.id === segmentId);
69	      if (!segment) {
70	        return;
71	      }
72	      const result = await updateSegmentAction({
73	        projectId,
74	        segmentId,
75	        targetText: segment.targetText ?? "",
76	        workId,
77	      });
78	      if (result.success) {
79	        setSegments(
80	          segmentsRef.current.map((item) =>
81	            item.id === segmentId
82	              ? { ...item, status: result.data.status }
83	              : item,
84	          ),
85	        );
86	        setSaved(true);
87	      }
88	    },
89	    [projectId, workId, setSegments],
90	  );
91	
92	  function updateLocalTarget(segmentId: string, value: string): void {
93	    dirtyRef.current.add(segmentId);
94	    setSaved(false);
95	    setSegments(
96	      segmentsRef.current.map((segment) =>
97	        segment.id === segmentId ? { ...segment, targetText: value } : segment,
98	      ),
99	    );
100	  }
101	
102	  function handleBlur(segmentId: string): void {
103	    if (!dirtyRef.current.has(segmentId)) {
104	      return;
105	    }
106	    dirtyRef.current.delete(segmentId);
107	    persistTarget(segmentId).catch(() => {});
108	  }
109	
110	  function handleSelect(segmentId: string): void {
111	    if (mode === "merge") {
112	      setMergeSelected((previous) => {
113	        const next = new Set(previous);
114	        if (next.has(segmentId)) {
115	          next.delete(segmentId);
116	        } else {
117	          next.add(segmentId);
118	        }
119	        return next;
120	      });
121	      return;
122	    }
123	    setSelectedId(segmentId);
124	  }
125	
126	  async function handleApply(text: string): Promise<void> {
127	    if (!selectedId) {
128	      return;
129	    }
130	    updateLocalTarget(selectedId, text);
131	    dirtyRef.current.delete(selectedId);
132	    await persistTarget(selectedId);
133	  }
134	
135	  async function handleConfirm(): Promise<void> {
136	    if (!selectedSegment) {
137	      return;
138	    }
139	    setConfirmError(null);
140	    setIsConfirming(true);
141	    if (dirtyRef.current.has(selectedSegment.id)) {
142	      dirtyRef.current.delete(selectedSegment.id);
143	      await persistTarget(selectedSegment.id);
144	    }
145	    const result = await confirmSegmentAction({
146	      projectId,
147	      segmentId: selectedSegment.id,
148	      workId,
149	    });
150	    setIsConfirming(false);
151	    if (result.success) {
152	      setSegments(
153	        segmentsRef.current.map((segment) =>
154	          segment.id === selectedSegment.id
155	            ? { ...segment, status: SegmentStatus.Confirmed }
156	            : segment,
157	        ),
158	      );
159	    } else {
160	      setConfirmError(result.error);
161	    }
162	  }
163	
164	  function toggleMode(target: Mode): void {
165	    setStructuralError(null);
166	    setMergeSelected(new Set());
167	    setMode((current) => (current === target ? "normal" : target));
168	  }
169	
170	  async function handleMerge(): Promise<void> {
171	    const ids = segments
172	      .filter((segment) => mergeSelected.has(segment.id))
173	      .map((segment) => segment.id);
174	    if (ids.length < 2) {
175	      return;
176	    }
177	    setStructuralError(null);
178	    const result = await mergeSegmentsAction({
179	      projectId,
180	      segmentIds: ids,
181	      workId,
182	    });
183	    if (result.success) {
184	      setSegments(result.data);
185	      setMergeSelected(new Set());
186	      setMode("normal");
187	      setSelectedId(ids[0] ?? null);
188	    } else {
189	      setStructuralError(result.error);
190	    }
191	  }
192	
193	  async function handleSplit(
194	    segmentId: string,
195	    splitIndex: number,
196	  ): Promise<void> {
197	    setStructuralError(null);
198	    const result = await splitSegmentAction({
199	      projectId,
200	      segmentId,
201	      splitIndex,
202	      workId,
203	    });
204	    if (result.success) {
205	      setSegments(result.data);
206	    } else {
207	      setStructuralError(result.error);
208	    }
209	  }
210	
211	  return (
212	    <div className="flex h-full flex-col">
213	      <div className="flex flex-wrap items-center gap-3 border-b bg-card px-4 py-2">
214	        <Button asChild size="sm" variant="ghost">
215	          <Link href={`/projects/${projectId}`}>← 戻る</Link>
216	        </Button>
217	        <span className="font-semibold">{workName}</span>
218	        <span className="text-xs text-muted-foreground">
219	          確定 {progress.confirmed}/{progress.total}
220	        </span>
221	        {saved && (
222	          <span className="text-xs text-green-600">● 自動保存しました</span>
223	        )}
224	        <div className="flex-1" />
225	        {canEdit && (
226	          <>
227	            <Button
228	              onClick={() => toggleMode("merge")}
229	              size="sm"
230	              variant={mode === "merge" ? "default" : "outline"}
231	            >
232	              <Combine className="size-4" />
233	              結合モード
234	            </Button>
235	            <Button
236	              onClick={() => toggleMode("split")}
237	              size="sm"
238	              variant={mode === "split" ? "default" : "outline"}
239	            >
240	              <Scissors className="size-4" />
241	              分割モード
242	            </Button>
243	          </>
244	        )}
245	        <Button asChild size="sm" variant="outline">
246	          {/* API ルートのためページ用 typedRoutes 対象外の素の anchor を使う */}
247	          <a download href={`/api/works/${workId}/export`}>
248	            <Download className="size-4" />
249	            バイリンガル CSV 出力
250	          </a>
251	        </Button>
252	      </div>
253	
254	      {mode === "merge" && (
255	        <div className="flex items-center gap-3 border-b bg-amber-50 px-4 py-2 text-sm text-amber-900 dark:bg-amber-950 dark:text-amber-100">
256	          <span>
257	            結合したい<b>連続するセグメント</b>をクリックで選択してください
258	          </span>
259	          <span className="font-medium">{mergeSelected.size} 文 選択中</span>
260	          <div className="flex-1" />
261	          <Button
262	            disabled={mergeSelected.size < 2}
263	            onClick={handleMerge}
264	            size="sm"
265	          >
266	            <Combine className="size-4" />
267	            選択した文を結合
268	          </Button>
269	        </div>
270	      )}
271	      {mode === "split" && (
272	        <div className="border-b bg-amber-50 px-4 py-2 text-sm text-amber-900 dark:bg-amber-950 dark:text-amber-100">
273	          文の区切りに出る <Scissors className="inline size-3.5" /> を
274	          クリックすると、その位置で 2 文に分割します
275	        </div>
276	      )}
277	      {structuralError && (
278	        <div
279	          className="border-b bg-destructive/10 px-4 py-2 text-sm text-destructive"
280	          role="alert"
281	        >
282	          {structuralError}
283	        </div>
284	      )}
285	
286	      <div className="flex min-h-0 flex-1">
287	        <div className="min-w-0 flex-1 overflow-auto bg-muted/30 p-3">
288	          <div className="grid grid-cols-[32px_1fr_1fr] gap-2 px-1 pb-2 text-[11px] tracking-wide text-muted-foreground uppercase">
289	            <div>#</div>
290	            <div>原文（日本語）</div>
291	            <div>訳文（英語）</div>
292	          </div>
293	          <div className="space-y-1.5">
294	            {segments.map((segment) => {
295	              const isSelected = mode === "normal" && segment.id === selectedId;
296	              const isMergeSelected = mergeSelected.has(segment.id);
297	              return (
298	                <div
299	                  className={`grid grid-cols-[32px_1fr_1fr] overflow-hidden rounded-md border bg-card ${
300	                    isSelected ? "border-ring ring-2 ring-ring/30" : ""
301	                  } ${isMergeSelected ? "border-ring bg-accent" : ""}`}
302	                  key={segment.id}
303	                  onClick={() => handleSelect(segment.id)}
304	                >
305	                  <div className="flex flex-col items-center gap-1 border-r bg-muted/50 pt-2 text-[11px] text-muted-foreground tabular-nums">
306	                    <SegmentStatusDot status={segment.status} />
307	                    {segment.seq}
308	                  </div>
309	                  <div className="border-r px-3 py-2 text-sm/relaxed">
310	                    {mode === "split" ? (
311	                      <SplitSource
312	                        onSplit={(index) => handleSplit(segment.id, index)}
313	                        text={segment.sourceText}
314	                      />
315	                    ) : (
316	                      segment.sourceText
317	                    )}
318	                  </div>
319	                  <div className="px-2 py-1">
320	                    <textarea
321	                      className="min-h-9 w-full resize-none bg-transparent px-1.5 py-1 text-sm/relaxed outline-none"
322	                      disabled={!canEdit || mode !== "normal"}
323	                      onBlur={() => handleBlur(segment.id)}
324	                      onChange={(event) =>
325	                        updateLocalTarget(segment.id, event.target.value)
326	                      }
327	                      onClick={(event) => event.stopPropagation()}
328	                      onFocus={() => handleSelect(segment.id)}
329	                      rows={1}
330	                      value={segment.targetText ?? ""}
331	                    />
332	                  </div>
333	                </div>
334	              );
335	            })}
336	          </div>
337	        </div>
338	
339	        <aside className="w-[380px] shrink-0 border-l bg-card">
340	          <AssistPanel
341	            canEdit={canEdit}
342	            confirmError={confirmError}
343	            isConfirming={isConfirming}
344	            key={selectedSegment?.id ?? "none"}
345	            onApply={handleApply}
346	            onConfirm={handleConfirm}
347	            projectId={projectId}
348	            segment={selectedSegment}
349	          />
350	        </aside>
351	      </div>
352	    </div>
353	  );
354	}
355	
356	function SplitSource({
357	  onSplit,
358	  text,
359	}: {
360	  onSplit: (index: number) => void;
361	  text: string;
362	}): React.JSX.Element {
363	  const parts = splitSentences(text);
364	
365	  return (
366	    <span>
367	      {parts.map((part, index) => (
368	        // 文の並びは安定しているため index キーで問題ない
369	
370	        <span key={index}>
371	          {part}
372	          {index < parts.length - 1 && (
373	            <button
374	              aria-label="ここで分割"
375	              className="mx-0.5 inline-flex size-4 items-center justify-center rounded-sm border border-amber-300 bg-amber-100 align-middle text-amber-700 hover:bg-amber-500 hover:text-white"
376	              onClick={(event) => {
377	                event.stopPropagation();
378	                onSplit(index);
379	              }}
380	              type="button"
381	            >
382	              <Scissors className="size-2.5" />
383	            </button>
384	          )}
385	        </span>
386	      ))}
387	    </span>
388	  );
389	}
