import type React from "react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@workspace/ui/components/table";
import { DeleteGlossaryDialog } from "@/features/glossary/delete/delete-glossary-dialog.client";
import type { CommonGlossaryItem } from "./get-common-glossaries";

export function CommonGlossaryPresenter({
  glossaries,
}: {
  glossaries: CommonGlossaryItem[];
}): React.JSX.Element {
  if (glossaries.length === 0) {
    return (
      <div className="py-12 text-center text-muted-foreground">
        用語が登録されていません。「用語を追加」から登録してください。
      </div>
    );
  }

  return (
    <Table>
      <TableHeader>
        <TableRow>
          <TableHead>原語</TableHead>
          <TableHead>訳語</TableHead>
          <TableHead>メモ</TableHead>
          <TableHead className="w-24">操作</TableHead>
        </TableRow>
      </TableHeader>
      <TableBody>
        {glossaries.map((glossary) => (
          <TableRow key={glossary.id}>
            <TableCell className="font-medium">{glossary.sourceTerm}</TableCell>
            <TableCell>{glossary.targetTerm}</TableCell>
            <TableCell className="text-muted-foreground">
              {glossary.note || "—"}
            </TableCell>
            <TableCell>
              <DeleteGlossaryDialog
                glossaryId={glossary.id}
                sourceTerm={glossary.sourceTerm}
              />
            </TableCell>
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
}

