"use client";

import type React from "react";
import { Button } from "@workspace/ui/components/button";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@workspace/ui/components/sheet";
import { Menu } from "lucide-react";
import Link from "next/link";
import { useEffect, useState } from "react";
import { OnboardingId } from "@/features/onboarding/constants/steps.universal";
import {
  PROJECTS_MENU_STEP_INDEX,
  useOnboarding,
} from "@/features/onboarding/hooks/use-onboarding.hook";

export function NavigationMenu(): React.JSX.Element {
  const { currentStep, refreshHighlight } = useOnboarding();
  const [open, setOpen] = useState(false);

  // オンボーディングのステップに応じてメニューを開閉
  useEffect(() => {
    let timeoutId: ReturnType<typeof setTimeout> | undefined;

    if (currentStep === PROJECTS_MENU_STEP_INDEX) {
      // オンボーディング中にメニューを自動で開く必要があるため意図的に effect 内で setState する
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setOpen(true);
      // シートが開き切った後にハイライトのサイズを修正するために resize イベント発行
      timeoutId = setTimeout(() => {
        refreshHighlight();
      }, 550);
    }

    return (): void => {
      clearTimeout(timeoutId);
    };
  }, [currentStep, refreshHighlight]);

  return (
    <Sheet onOpenChange={setOpen} open={open}>
      <SheetTrigger asChild>
        <Button id={OnboardingId.MenuButton} size="icon" variant="ghost">
          <Menu className="size-6" />
          <span className="sr-only">メニューを開く</span>
        </Button>
      </SheetTrigger>
      <SheetContent side="left">
        <SheetHeader>
          <SheetTitle>メニュー</SheetTitle>
        </SheetHeader>
        <nav className="mt-6">
          <ul className="space-y-2">
            <li>
              <Link
                className="block rounded-md px-4 py-2 text-sm font-medium text-neutral-700 hover:bg-neutral-100 hover:text-neutral-900"
                href="/"
                onClick={() => setOpen(false)}
              >
                トップページ
              </Link>
            </li>
            <li>
              <Link
                className="block rounded-md px-4 py-2 text-sm font-medium text-neutral-700 hover:bg-neutral-100 hover:text-neutral-900"
                href="/projects"
                id={OnboardingId.ProjectsMenu}
                onClick={() => setOpen(false)}
              >
                プロジェクト
              </Link>
            </li>
            <li>
              <Link
                className="block rounded-md px-4 py-2 text-sm font-medium text-neutral-700 hover:bg-neutral-100 hover:text-neutral-900"
                href="/glossary"
                onClick={() => setOpen(false)}
              >
                共通用語集
              </Link>
            </li>
            <li>
              <Link
                className="block rounded-md px-4 py-2 text-sm font-medium text-neutral-700 hover:bg-neutral-100 hover:text-neutral-900"
                href="/translation-memory"
                onClick={() => setOpen(false)}
              >
                翻訳メモリ
              </Link>
            </li>
            <li>
              <Link
                className="block rounded-md px-4 py-2 text-sm font-medium text-neutral-700 hover:bg-neutral-100 hover:text-neutral-900"
                href="/staffs"
                onClick={() => setOpen(false)}
              >
                ユーザー
              </Link>
            </li>
          </ul>
        </nav>
      </SheetContent>
    </Sheet>
  );
}

