"use client";

import type React from "react";
import { Badge } from "@workspace/ui/components/badge";
import { Button } from "@workspace/ui/components/button";
import { Loader2, Sparkles } from "lucide-react";
import { useEffect, useState } from "react";
import { getSegmentAssistAction } from "./get-segment-assist.action";
import type { SegmentDto } from "./get-work-segments";
import { SegmentStatusBadge } from "./segment-status-badge.universal";
import type { SegmentAssist } from "./assist-types";
import { translateSegmentAction } from "./translate-segment.action";

interface AssistPanelProps {
  canEdit: boolean;
  confirmError: string | null;
  isConfirming: boolean;
  onApply: (text: string) => void;
  onConfirm: () => void;
  projectId: string;
  segment: SegmentDto | null;
}

export function AssistPanel({
  canEdit,
  confirmError,
  isConfirming,
  onApply,
  onConfirm,
  projectId,
  segment,
}: AssistPanelProps): React.JSX.Element {
  // このコンポーネントはエディタ側で segment.id を key にして再マウントされるため、
  // セグメント切り替え時に state はリセットされる（effect 内での同期 setState を避ける）。
  const segmentId = segment?.id ?? null;
  const [candidate, setCandidate] = useState<string | null>(null);
  const [isTranslating, setIsTranslating] = useState(false);
  const [translateError, setTranslateError] = useState<string | null>(null);
  const [assist, setAssist] = useState<SegmentAssist | null>(null);
  const [isLoadingAssist, setIsLoadingAssist] = useState(segmentId !== null);

  useEffect(() => {
    if (!segmentId) {
      return;
    }

    let active = true;
    getSegmentAssistAction({ projectId, segmentId })
      .then((result) => {
        if (!active) {
          return;
        }
        setIsLoadingAssist(false);
        if (result.success) {
          setAssist(result.data);
        }
      })
      .catch(() => {});

    return (): void => {
      active = false;
    };
  }, [segmentId, projectId]);

  function handleTranslate(): void {
    if (!segmentId) {
      return;
    }
    setTranslateError(null);
    setIsTranslating(true);
    translateSegmentAction({ projectId, segmentId })
      .then((result) => {
        setIsTranslating(false);
        if (result.success) {
          setCandidate(result.data.translation);
        } else {
          setTranslateError(result.error);
        }
      })
      .catch(() => {
        setIsTranslating(false);
        setTranslateError("AI 英訳の生成に失敗しました");
      });
  }

  if (!segment) {
    return (
      <div className="flex h-full items-center justify-center p-8 text-center text-sm text-muted-foreground">
        セグメントを選択すると、AI 英訳候補・類似の過去訳・用語集が表示されます
      </div>
    );
  }

  return (
    <div className="flex h-full flex-col overflow-auto">
      <div className="sticky top-0 z-10 flex items-center justify-between gap-2 border-b bg-card p-3">
        <div className="flex items-center gap-2">
          <SegmentStatusBadge status={segment.status} />
          <span className="text-xs text-muted-foreground">
            セグメント #{segment.seq}
          </span>
        </div>
        {canEdit && (
          <Button
            disabled={isConfirming || !segment.targetText?.trim()}
            isProcessing={isConfirming}
            onClick={onConfirm}
            processingLabel="確定中"
            size="sm"
          >
            確定
          </Button>
        )}
      </div>

      <div className="space-y-4 p-3">
        <div className="rounded-md bg-muted p-2 text-xs text-foreground">
          {segment.sourceText}
        </div>
        {confirmError && (
          <div className="text-sm text-destructive" role="alert">
            {confirmError}
          </div>
        )}

        {canEdit && (
          <section className="space-y-2">
            <h4 className="flex items-center gap-1.5 text-xs font-medium tracking-wide text-muted-foreground uppercase">
              <Sparkles className="size-3.5" />
              AI 英訳候補
            </h4>
            {candidate ? (
              <div className="rounded-md border border-blue-200 bg-blue-50 p-2.5 text-sm text-blue-900 dark:border-blue-900 dark:bg-blue-950 dark:text-blue-100">
                {candidate}
              </div>
            ) : (
              <p className="text-xs text-muted-foreground">
                「AI 生成」で原文を英訳します。類似の過去訳・用語集を
                ヒントとして渡します。
              </p>
            )}
            <div className="flex gap-2">
              {candidate && (
                <Button
                  className="flex-1"
                  onClick={() => onApply(candidate)}
                  size="sm"
                >
                  訳文に挿入
                </Button>
              )}
              <Button
                disabled={isTranslating}
                isProcessing={isTranslating}
                onClick={handleTranslate}
                processingLabel="生成中"
                size="sm"
                variant="outline"
              >
                <Sparkles className="size-4" />
                {candidate ? "再生成" : "AI 生成"}
              </Button>
            </div>
            {translateError && (
              <div className="text-sm text-destructive" role="alert">
                {translateError}
              </div>
            )}
          </section>
        )}

        <section className="space-y-2">
          <h4 className="flex items-center gap-2 text-xs font-medium tracking-wide text-muted-foreground uppercase">
            類似の過去訳（TM）
            <Badge variant="secondary">類似度70%以上</Badge>
          </h4>
          {isLoadingAssist ? (
            <Loader2 className="size-4 animate-spin text-muted-foreground" />
          ) : assist && assist.tmMatches.length > 0 ? (
            <ul className="space-y-2">
              {assist.tmMatches.map((tm) => (
                <li key={tm.id}>
                  <button
                    className="w-full rounded-md border p-2 text-left hover:bg-muted"
                    onClick={() => canEdit && onApply(tm.targetText)}
                    type="button"
                  >
                    <div className="text-xs text-muted-foreground">
                      {tm.sourceText}
                    </div>
                    <div className="mt-0.5 text-xs">{tm.targetText}</div>
                    <div className="mt-1 flex items-center justify-between">
                      <span className="text-[11px] text-muted-foreground">
                        {tm.projectName}
                      </span>
                      <span className="text-[11px] font-medium text-green-600">
                        類似度 {Math.round(tm.score * 100)}%
                      </span>
                    </div>
                  </button>
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-xs text-muted-foreground">
              類似の過去訳はありません
            </p>
          )}
        </section>

        <section className="space-y-2">
          <h4 className="flex items-center gap-2 text-xs font-medium tracking-wide text-muted-foreground uppercase">
            用語集マッチ
            <Badge variant="secondary">上位5</Badge>
          </h4>
          {assist && assist.glossaryMatches.length > 0 ? (
            <ul className="space-y-1">
              {assist.glossaryMatches.map((glossary) => (
                <li
                  className="flex items-center gap-2 border-b border-dashed py-1 text-xs last:border-b-0"
                  key={`${glossary.sourceTerm}-${glossary.targetTerm}`}
                >
                  <span className="text-muted-foreground">
                    {glossary.sourceTerm}
                  </span>
                  <span className="text-muted-foreground/50">→</span>
                  <span className="font-medium">{glossary.targetTerm}</span>
                  {glossary.isCommon && (
                    <Badge className="ml-auto" variant="outline">
                      共通
                    </Badge>
                  )}
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-xs text-muted-foreground">
              一致する用語はありません
            </p>
          )}
        </section>
      </div>
    </div>
  );
}

content.text:
新しいメッセージが続いているので、まず質問にお答えし、その後エディタの設計方針を整理して確認させてください。

## 質問への回答：類似の過去訳は useSWR + route api か？

**いいえ、どちらも使っていません。** 実装は **Server Action を `useEffect` 内で呼ぶ** 方式です（`assist-panel.client.tsx:42-63`）。

```tsx
useEffect(() => {
  if (!segmentId) return;
  let active = true;
  getSegmentAssistAction({ projectId, segmentId })   // ← Server Action
    .then((result) => {
      if (!active) return;
      setIsLoadingAssist(false);
      if (result.success) setAssist(result.data);
    })
    .catch(() => {});
  return () => { active = false; };
}, [segmentId, projectId]);
```

- **useSWR ではない**：`useState`（`assist` / `isLoadingAssist`）と `active` フラグでローディング・キャンセルを手動管理しています。
- **route API (route handler) でもない**：`getSegmentAssistAction`（Server Action）経由です。類似の過去訳(`tmMatches`)・用語集マッチ(`glossaryMatches`)を1回のアクションでまとめて取得しています。
- このプロジェクトで `route.ts`（API ルート）を使っているのは、確認した範囲では **バイリンガル CSV 出力（`/api/works/[workId]/export`）だけ**です。

---

## エディタ設計の方針確認

ここまでのメッセージから、対訳エディタの保存モデルをこう変えたい、と理解しました：

1. **blur での自動保存を廃止**
2. **編集中（dirty＝未保存のローカル変更）を「下書き」として表現**
3. キャンセルでローカル変更を破棄 → 元の状態（未入力／確定）に戻す

この方針だと、以前お伝えした「キャンセル時にDBへ書き戻す」問題が**消えます**。自動保存しなければ、編集中はDBに何も書かれていないので、キャンセルは単にローカル state を捨てるだけで済み、未入力なら未入力・確定なら確定に自然に戻ります。設計がシンプルになります。

ただ、ここで詰めるべき重要な点が残っています。メッセージが途中（「確定していない(」）だったので、続きと合わせて教えてください。

- **下書きはDBに保存しますか？** 自動保存をやめた場合、下書きを永続化する手段が必要です。選択肢は:
  - (A) 「下書き保存」ボタンを設けて明示的に保存（DBに status=下書きで残る）
  - (B) 下書きは**画面上だけの一時状態**にして、DBに残すのは「確定」したものだけ（離脱すると下書きは消える）
- **確定ボタンの挙動**は現状どおり（訳文を保存して確定）でよいですか？

---

なお、**用語集の実装は中断中**です（認可ヘルパー1ファイルを作成済み、既存への影響なし）。エディタの件が固まってから再開しますか？ それとも用語集を先に仕上げますか？ ご指示ください。

