1	"use client";
2	
3	import type React from "react";
4	import type { SegmentStatus } from "@workspace/db/schema/segment";
5	import { Badge } from "@workspace/ui/components/badge";
6	import { Button } from "@workspace/ui/components/button";
7	import { Loader2, Sparkles } from "lucide-react";
8	import { useEffect, useState } from "react";
9	import { getSegmentAssistAction } from "./get-segment-assist.action";
10	import type { SegmentDto } from "./get-work-segments";
11	import { SegmentStatusBadge } from "./segment-status-badge.universal";
12	import type { SegmentAssist } from "./assist-types";
13	import { translateSegmentAction } from "./translate-segment.action";
14	
15	interface AssistPanelProps {
16	  canEdit: boolean;
17	  confirmError: string | null;
18	  displayStatus: SegmentStatus;
19	  isConfirming: boolean;
20	  isDirty: boolean;
21	  onApply: (text: string) => void;
22	  onCancel: () => void;
23	  onConfirm: () => void;
24	  projectId: string;
25	  segment: SegmentDto | null;
26	}
27	
28	export function AssistPanel({
29	  canEdit,
30	  confirmError,
31	  displayStatus,
32	  isConfirming,
33	  isDirty,
34	  onApply,
35	  onCancel,
36	  onConfirm,
37	  projectId,
38	  segment,
39	}: AssistPanelProps): React.JSX.Element {
40	  // このコンポーネントはエディタ側で segment.id を key にして再マウントされるため、
41	  // セグメント切り替え時に state はリセットされる（effect 内での同期 setState を避ける）。
42	  const segmentId = segment?.id ?? null;
43	  const [candidate, setCandidate] = useState<string | null>(null);
44	  const [isTranslating, setIsTranslating] = useState(false);
45	  const [translateError, setTranslateError] = useState<string | null>(null);
46	  const [assist, setAssist] = useState<SegmentAssist | null>(null);
47	  const [isLoadingAssist, setIsLoadingAssist] = useState(segmentId !== null);
48	
49	  useEffect(() => {
50	    if (!segmentId) {
51	      return;
52	    }
53	
54	    let active = true;
55	    getSegmentAssistAction({ projectId, segmentId })
56	      .then((result) => {
57	        if (!active) {
58	          return;
59	        }
60	        setIsLoadingAssist(false);
61	        if (result.success) {
62	          setAssist(result.data);
63	        }
64	      })
65	      .catch(() => {});
66	
