          ) : assist && assist.tmMatches.length > 0 ? (
            <ul className="space-y-2">
              {assist.tmMatches.map((tm) => (
                <li key={tm.id}>
                  <button
                    className="w-full rounded-md border p-2 text-left hover:bg-muted"
