                  <span className="font-medium">{glossary.targetTerm}</span>
                  {glossary.isCommon && (
                    <Badge className="ml-auto" variant="outline">
                      共通
                    </Badge>
                  )}
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-xs text-muted-foreground">
              一致する用語はありません
            </p>
          )}
        </section>
      </div>
    </div>
  );
}
